class StreamChecker {
    private static class TrieNode {
        TrieNode[] children = new TrieNode[26];
        boolean isWord = false;
    }

    private final TrieNode root;
    private final StringBuilder stream;
    private final int maxWordLength;

    public StreamChecker(String[] words) {
        root = new TrieNode();
        stream = new StringBuilder();
        int maxLen = 0;
        for (String word : words) {
            maxLen = Math.max(maxLen, word.length());
            insert(word);
        }
        maxWordLength = maxLen;
    }

    private void insert(String word) {
        TrieNode node = root;
        // Insert reversed word into trie
        for (int i = word.length() - 1; i >= 0; i--) {
            int idx = word.charAt(i) - 'a';
            if (node.children[idx] == null) {
                node.children[idx] = new TrieNode();
            }
            node = node.children[idx];
        }
        node.isWord = true;
    }

    public boolean query(char letter) {
        stream.append(letter);
        TrieNode node = root;
        // Traverse the stream from the end backwards, up to maxWordLength
        for (int i = stream.length() - 1; i >= 0 && stream.length() - 1 - i < maxWordLength; i--) {
            int idx = stream.charAt(i) - 'a';
            if (node.children[idx] == null) {
                return false;
            }
            node = node.children[idx];
            if (node.isWord) {
                return true;
            }
        }
        return false;
    }
}

